diffs.before:
name: Nimbus PR Review

on:
  pull_request:
    types: [opened, synchronize]

concurrency:
  group: nimbus-pr-review-${{ github.ref }}
  cancel-in-progress: true

permissions:
  contents: read
  pull-requests: write
  issues: write

jobs:
  nimbus-review:
    if: github.event_name == 'pull_request'
    name: Nimbus Review (informational)
    runs-on: ubuntu-latest
    timeout-minutes: 10

    steps:
      - name: Detect trusted PR context
        id: pr_context
        uses: actions/github-script@v7
        with:
          script: |
            const pr = context.payload.pull_request;
            const repoFullName = `${context.repo.owner}/${context.repo.repo}`;
            const headRepoId = pr?.head?.repo?.id;
            const baseRepoId = context.payload.repository?.id;
            const authorLogin = pr?.user?.login;

            let hasWriteLikeAccess = false;
            if (authorLogin) {
              try {
                const permission = await github.rest.repos.getCollaboratorPermissionLevel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  username: authorLogin,
                });
                const level = permission.data.permission;
                hasWriteLikeAccess = level === 'admin' || level === 'maintain' || level === 'write';
              } catch (error) {
                core.warning(`Could not resolve collaborator permission for ${authorLogin}; treating PR as untrusted.`);
              }
            }

            const trusted =
              pr?.head?.repo?.fork === false &&
              Number.isInteger(headRepoId) &&
              Number.isInteger(baseRepoId) &&
              headRepoId === baseRepoId &&
              pr?.head?.repo?.full_name === repoFullName &&
              pr?.head?.repo?.owner?.login === context.repo.owner &&
              hasWriteLikeAccess;

            core.setOutput('trusted_pr', trusted ? 'true' : 'false');
            if (!trusted) {
              core.warning('Untrusted PR context detected (fork/repository mismatch or missing write permissions). Nimbus review steps requiring repository secrets will be skipped.');
            }

      - name: Checkout
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Fetch Entire checkpoint branch
        continue-on-error: true
        run: |
          # Required for local Entire context/co-change resolution in CI.
          # If this branch doesn't exist yet, the review will still run
          # but without local co-change context.
          if git fetch --no-tags origin entire/checkpoints/v1:refs/remotes/origin/entire/checkpoints/v1; then
            echo "ENTIRE_CHECKPOINTS_FETCHED=true" >> "$GITHUB_ENV"
          else
            echo "ENTIRE_CHECKPOINTS_FETCHED=false" >> "$GITHUB_ENV"
            echo "::warning::Could not fetch origin/entire/checkpoints/v1. Continuing without local Entire co-change context."
          fi

      - name: Setup pnpm
        uses: pnpm/action-setup@v4

      - name: Setup Node
        uses: actions/setup-node@v4
        with:
          node-version: 20
          cache: pnpm

      - name: Install dependencies
        run: pnpm install --frozen-lockfile

      # Dogfood invocation for monorepo development.
      # When extracted to standalone nimbus-action, replace with globally-installed CLI:
      # nimbus review create --commit <sha> --base <ref>
      - name: Refresh PR base ref
        if: steps.pr_context.outputs.trusted_pr == 'true'
        run: |
          git fetch --no-tags origin "${{ github.event.pull_request.base.ref }}:refs/remotes/origin/${{ github.event.pull_request.base.ref }}"

      - name: Run Nimbus review create (non-blocking)
        id: create_review
        if: steps.pr_context.outputs.trusted_pr == 'true'
        continue-on-error: true
        env:
          HEAD_SHA: ${{ github.event.pull_request.head.sha }}
          BASE_REF: origin/${{ github.event.pull_request.base.ref }}
          NIMBUS_API_KEY: ${{ secrets.NIMBUS_API_KEY }}
          REVIEW_CONTEXT_GITHUB_TOKEN: ${{ secrets.REVIEW_CONTEXT_GITHUB_TOKEN }}
        run: |
          pnpm --filter @dayhaysoos/nimbus dev review create \
            --commit "${HEAD_SHA}" \
            --base "${BASE_REF}" \
            --output-review-id "$GITHUB_WORKSPACE/nimbus-review-id.txt"

      - name: Read review ID
        id: parse_review_id
        if: always() && steps.pr_context.outputs.trusted_pr == 'true'
        env:
          CREATE_OUTCOME: ${{ steps.create_review.outcome }}
        run: |
          # Try file first (reliable)
          REVIEW_ID=$(cat "$GITHUB_WORKSPACE/nimbus-review-id.txt" 2>/dev/null || echo "")

          if [ -z "${REVIEW_ID}" ]; then
            echo "::warning::Review ID file was not produced (create step outcome: ${CREATE_OUTCOME:-unknown}). Markdown export will be skipped. Re-run this workflow if review creation failed unexpectedly."
          fi

          echo "review_id=${REVIEW_ID}" >> "$GITHUB_OUTPUT"
          echo "Parsed review_id='${REVIEW_ID}'"

      - name: Export review markdown (non-blocking)
        id: export_markdown
        if: always() && steps.pr_context.outputs.trusted_pr == 'true' && steps.create_review.outcome == 'success' && steps.parse_review_id.outputs.review_id != ''
        continue-on-error: true
        env:
          NIMBUS_API_KEY: ${{ secrets.NIMBUS_API_KEY }}
        run: |
          pnpm --filter @dayhaysoos/nimbus dev review export "${{ steps.parse_review_id.outputs.review_id }}" --format markdown --out "$GITHUB_WORKSPACE/nimbus-review.md"

      - name: Upsert sticky PR comment
        if: always()
        uses: actions/github-script@v7
        env:
          TRUSTED_PR: ${{ steps.pr_context.outputs.trusted_pr }}
          SECRETS_READY: ${{ steps.create_review.outcome != 'skipped' && 'true' || 'false' }}
          REVIEW_ID: ${{ steps.parse_review_id.outputs.review_id }}
          CREATE_OUTCOME: ${{ steps.create_review.outcome }}
          EXPORT_OUTCOME: ${{ steps.export_markdown.outcome }}
          ENTIRE_CHECKPOINTS_FETCHED: ${{ env.ENTIRE_CHECKPOINTS_FETCHED }}
        with:
          script: |
            const fs = require('fs');

            const marker = '<!-- nimbus-review-comment -->';
            const reviewId = process.env.REVIEW_ID || '';
            const createOutcome = process.env.CREATE_OUTCOME || 'unknown';
            const exportOutcome = process.env.EXPORT_OUTCOME || 'skipped';
            const trustedPr = process.env.TRUSTED_PR || 'unknown';
            const secretsReady = process.env.SECRETS_READY || 'unknown';
            const checkpointsFetched = process.env.ENTIRE_CHECKPOINTS_FETCHED || 'unknown';
            const workspace = process.env.GITHUB_WORKSPACE || process.cwd();
            const markdownPath = `${workspace}/nimbus-review.md`;

            const pr = context.payload.pull_request;
            const headSha = pr.head.sha;
            const baseRef = pr.base.ref;
            const runUrl = `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;

            // Re-check freshness at update time to narrow race window between stale_guard and comment upsert.
            const latest = await github.rest.pulls.get({ owner: context.repo.owner, repo: context.repo.repo, pull_number: pr.number });
            const staleContext = latest.data.head.sha !== headSha
              ? {
                  triggerHead: headSha,
                  currentHead: latest.data.head.sha,
                }
              : null;
            if (staleContext) {
              core.warning(`Run became stale before comment update. Trigger head=${staleContext.triggerHead}, current head=${staleContext.currentHead}`);
            }

            let body = `${marker}
            ## Nimbus Review

            - Commit: \`${headSha}\`
            - Base: \`${baseRef}\`
            - Create step: \`${createOutcome}\`
            - Export step: \`${exportOutcome}\`
            - Trusted PR context: \`${trustedPr}\`
            - Required secrets ready: \`${secretsReady}\`
            - Entire checkpoints ref fetched: \`${checkpointsFetched}\`
            - Workflow run: ${runUrl}
            `;

            if (checkpointsFetched !== 'true') {
              body += `

            > ⚠️ Entire checkpoint ref fetch failed in CI. Review may run without local co-change context, which can reduce result quality.
            `;
            }

            if (staleContext) {
              body += `

            ---
            Nimbus skipped posting run findings for stale commit \`${staleContext.triggerHead}\` because PR head advanced to \`${staleContext.currentHead}\` during execution.
            A newer run should post fresh findings for the current head.
            `;
            } else if (trustedPr !== 'true') {
              body += `

            ---
            Nimbus review was skipped for this run because this PR context is not trusted.
            Repository secrets are only used for same-repo pull requests authored by users with write-level repository access.
            `;
            } else if (secretsReady !== 'true') {
              body += `

            ---
            Nimbus review was skipped because required workflow secrets are not configured.
            Add required secrets and re-run the workflow.
            `;
            } else if (reviewId && fs.existsSync(markdownPath)) {
              const markdown = fs.readFileSync(markdownPath, 'utf8').trim();
              const noFindings = /- Findings:\s*0\b/.test(markdown);
              body += `

            ---
            ${noFindings ? '✅ No actionable findings detected in this run.\n\n' : ''}${markdown}
            `;
            } else if (createOutcome !== 'success') {
              body += `

            ---
            Nimbus review create did not complete successfully, so no review ID was available for export.
            Check workflow logs for the create-step failure details.
            `;
            } else {
              body += `

            ---
            Nimbus review did not produce an exportable markdown report in this run.
            Check workflow logs for details.
            `;
            }

            const suffix = '\n\n... (truncated)';
            const max = 65536;
            const maxBeforeSuffix = max - suffix.length;
            if (body.length > maxBeforeSuffix) {
              body = body.slice(0, maxBeforeSuffix) + suffix;
            }

            const { owner, repo } = context.repo;
            const issue_number = pr.number;

            const comments = await github.paginate(github.rest.issues.listComments, {
              owner,
              repo,
              issue_number,
              per_page: 100,
            });

            const existing = comments.find(c =>
              c.user?.type === 'Bot' &&
              typeof c.body === 'string' &&
              c.body.includes(marker)
            );

            if (existing) {
              await github.rest.issues.updateComment({
                owner,
                repo,
                comment_id: existing.id,
                body,
              });
              core.info(`Updated existing Nimbus comment: ${existing.id}`);
            } else {
              const created = await github.rest.issues.createComment({
                owner,
                repo,
                issue_number,
                body,
              });
              core.info(`Created Nimbus comment: ${created.data.id}`);
            }

      - name: Finalize as informational check
        if: always()
        run: |
          echo "Nimbus PR review completed (informational mode)."
          exit 0

diffs.after:
name: Nimbus PR Review

on:
  pull_request:
    types: [opened, synchronize]

concurrency:
  group: "nimbus-pr-review-pr-${{ github.event.pull_request.number || github.ref }}"
  cancel-in-progress: true

permissions:
  contents: read
  pull-requests: write
  issues: write
  checks: write

jobs:
  nimbus-review:
    if: github.event_name == 'pull_request'
    name: Nimbus Review (informational)
    runs-on: ubuntu-latest
    timeout-minutes: 10

    steps:
      - name: Detect trusted PR context
        id: pr_context
        uses: actions/github-script@v7
        with:
          script: |
            const pr = context.payload.pull_request;
            const repoFullName = `${context.repo.owner}/${context.repo.repo}`;
            const headRepoId = pr?.head?.repo?.id;
            const baseRepoId = context.payload.repository?.id;
            const authorLogin = pr?.user?.login;

            let hasWriteLikeAccess = false;
            if (authorLogin) {
              try {
                const permission = await github.rest.repos.getCollaboratorPermissionLevel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  username: authorLogin,
                });
                const level = permission.data.permission;
                hasWriteLikeAccess = level === 'admin' || level === 'maintain' || level === 'write';
              } catch (error) {
                core.warning(`Could not resolve collaborator permission for ${authorLogin}; treating PR as untrusted.`);
              }
            }

            const trusted =
              pr?.head?.repo?.fork === false &&
              Number.isInteger(headRepoId) &&
              Number.isInteger(baseRepoId) &&
              headRepoId === baseRepoId &&
              pr?.head?.repo?.full_name === repoFullName &&
              pr?.head?.repo?.owner?.login === context.repo.owner &&
              hasWriteLikeAccess;

            core.setOutput('trusted_pr', trusted ? 'true' : 'false');
            if (!trusted) {
              core.warning('Untrusted PR context detected (fork/repository mismatch or missing write permissions). Nimbus review steps requiring repository secrets will be skipped.');
            }

      - name: Checkout
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Fetch Entire checkpoint branch
        continue-on-error: true
        run: |
          # Required for local Entire context/co-change resolution in CI.
          # If this branch doesn't exist yet, the review will still run
          # but without local co-change context.
          if git fetch --no-tags origin entire/checkpoints/v1:refs/remotes/origin/entire/checkpoints/v1; then
            echo "ENTIRE_CHECKPOINTS_FETCHED=true" >> "$GITHUB_ENV"
          else
            echo "ENTIRE_CHECKPOINTS_FETCHED=false" >> "$GITHUB_ENV"
            echo "::warning::Could not fetch origin/entire/checkpoints/v1. Continuing without local Entire co-change context."
          fi

      - name: Setup pnpm
        uses: pnpm/action-setup@v4

      - name: Setup Node
        uses: actions/setup-node@v4
        with:
          node-version: 20
          cache: pnpm

      - name: Install dependencies
        run: pnpm install --frozen-lockfile

      # Dogfood invocation for monorepo development.
      # When extracted to standalone nimbus-action, replace with globally-installed CLI:
      # nimbus review create --commit <sha> --base <ref>
      - name: Refresh PR base ref
        if: steps.pr_context.outputs.trusted_pr == 'true'
        run: |
          git fetch --no-tags origin "${{ github.event.pull_request.base.ref }}:refs/remotes/origin/${{ github.event.pull_request.base.ref }}"

      - name: Run Nimbus review create (non-blocking)
        id: create_review
        if: steps.pr_context.outputs.trusted_pr == 'true'
        continue-on-error: true
        env:
          HEAD_SHA: ${{ github.event.pull_request.head.sha }}
          BASE_REF: origin/${{ github.event.pull_request.base.ref }}
          NIMBUS_API_KEY: ${{ secrets.NIMBUS_API_KEY }}
          REVIEW_CONTEXT_GITHUB_TOKEN: ${{ secrets.REVIEW_CONTEXT_GITHUB_TOKEN }}
        run: |
          pnpm --filter @dayhaysoos/nimbus dev review create \
            --commit "${HEAD_SHA}" \
            --base "${BASE_REF}" \
            --output-review-id "$GITHUB_WORKSPACE/nimbus-review-id.txt"

      - name: Read review ID
        id: parse_review_id
        if: always() && steps.pr_context.outputs.trusted_pr == 'true'
        env:
          CREATE_OUTCOME: ${{ steps.create_review.outcome }}
        run: |
          # Try file first (reliable)
          REVIEW_ID=$(cat "$GITHUB_WORKSPACE/nimbus-review-id.txt" 2>/dev/null || echo "")

          if [ -z "${REVIEW_ID}" ]; then
            echo "::warning::Review ID file was not produced (create step outcome: ${CREATE_OUTCOME:-unknown}). Markdown export will be skipped. Re-run this workflow if review creation failed unexpectedly."
          fi

          echo "review_id=${REVIEW_ID}" >> "$GITHUB_OUTPUT"
          echo "Parsed review_id='${REVIEW_ID}'"

      - name: Export review markdown (non-blocking)
        id: export_markdown
        if: always() && steps.pr_context.outputs.trusted_pr == 'true' && steps.create_review.outcome == 'success' && steps.parse_review_id.outputs.review_id != ''
        continue-on-error: true
        env:
          NIMBUS_API_KEY: ${{ secrets.NIMBUS_API_KEY }}
        run: |
          pnpm --filter @dayhaysoos/nimbus dev review export "${{ steps.parse_review_id.outputs.review_id }}" --format markdown --out "$GITHUB_WORKSPACE/nimbus-review.md"

      - name: Publish Nimbus findings check run
        id: publish_check
        if: always()
        continue-on-error: true
        uses: actions/github-script@v7
        env:
          TRUSTED_PR: ${{ steps.pr_context.outputs.trusted_pr }}
          SECRETS_READY: ${{ steps.create_review.outcome != 'skipped' && 'true' || 'false' }}
          REVIEW_ID: ${{ steps.parse_review_id.outputs.review_id }}
          CREATE_OUTCOME: ${{ steps.create_review.outcome }}
          EXPORT_OUTCOME: ${{ steps.export_markdown.outcome }}
          ENTIRE_CHECKPOINTS_FETCHED: ${{ env.ENTIRE_CHECKPOINTS_FETCHED }}
        with:
          script: |
            const fs = require('fs');

            const reviewId = process.env.REVIEW_ID || '';
            const createOutcome = process.env.CREATE_OUTCOME || 'unknown';
            const exportOutcome = process.env.EXPORT_OUTCOME || 'skipped';
            const trustedPr = process.env.TRUSTED_PR || 'unknown';
            const secretsReady = process.env.SECRETS_READY || 'unknown';
            const checkpointsFetched = process.env.ENTIRE_CHECKPOINTS_FETCHED || 'unknown';
            const workspace = process.env.GITHUB_WORKSPACE || process.cwd();
            const markdownPath = `${workspace}/nimbus-review.md`;

            const pr = context.payload.pull_request;
            const headSha = pr.head.sha;
            const baseRef = pr.base.ref;
            const runUrl = `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;

            const latest = await github.rest.pulls.get({ owner: context.repo.owner, repo: context.repo.repo, pull_number: pr.number });
            const staleContext = latest.data.head.sha !== headSha
              ? {
                  triggerHead: headSha,
                  currentHead: latest.data.head.sha,
                }
              : null;

            let summary = [
              `Commit: \`${headSha}\``,
              `Base: \`${baseRef}\``,
              `Create step: \`${createOutcome}\``,
              `Export step: \`${exportOutcome}\``,
              `Trusted PR context: \`${trustedPr}\``,
              `Required secrets ready: \`${secretsReady}\``,
              `Entire checkpoints ref fetched: \`${checkpointsFetched}\``,
              `Workflow run: ${runUrl}`,
            ].join('\n');

            let findingsCount = '';
            let noFindings = false;

            if (checkpointsFetched !== 'true') {
              summary += '\n\n> Entire checkpoint ref fetch failed in CI. Review may run without local co-change context.';
            }

            if (staleContext) {
              summary += `\n\nRun became stale before findings publication. Trigger head=\`${staleContext.triggerHead}\`, current head=\`${staleContext.currentHead}\`.`;
            } else if (trustedPr !== 'true') {
              summary += '\n\nNimbus review was skipped because this PR context is not trusted.';
            } else if (secretsReady !== 'true') {
              summary += '\n\nNimbus review was skipped because required workflow secrets are not configured.';
            } else if (reviewId && fs.existsSync(markdownPath)) {
              const markdown = fs.readFileSync(markdownPath, 'utf8').trim();
              const findingsMatch = markdown.match(/- Findings:\s*(\d+)\b/);
              findingsCount = findingsMatch ? findingsMatch[1] : '';
              noFindings = findingsCount === '0';
              summary += `\n\n---\n\n${markdown}`;
            } else if (createOutcome !== 'success') {
              summary += '\n\nNimbus review create did not complete successfully, so no review ID was available for export.';
            } else {
              summary += '\n\nNimbus review did not produce an exportable markdown report in this run.';
            }

            const maxSummary = 65000;
            if (summary.length > maxSummary) {
              summary = summary.slice(0, maxSummary) + '\n\n... (truncated)';
            }

            const conclusion = noFindings ? 'success' : 'neutral';
            const title = noFindings ? 'Nimbus Findings (no issues)' : 'Nimbus Findings';

            const checkRun = await github.rest.checks.create({
              owner: context.repo.owner,
              repo: context.repo.repo,
              name: 'Nimbus Findings',
              head_sha: headSha,
              status: 'completed',
              conclusion,
              details_url: runUrl,
              external_id: reviewId || undefined,
              output: {
                title,
                summary,
              },
            });

            core.setOutput('conclusion', conclusion);
            core.setOutput('findings_count', findingsCount);
            core.setOutput('stale', staleContext ? 'true' : 'false');
            core.setOutput('check_id', String(checkRun.data.id));

      - name: Upsert sticky PR comment
        if: always()
        continue-on-error: true
        uses: actions/github-script@v7
        env:
          CHECK_CONCLUSION: ${{ steps.publish_check.outputs.conclusion }}
          FINDINGS_COUNT: ${{ steps.publish_check.outputs.findings_count }}
          STALE_RUN: ${{ steps.publish_check.outputs.stale }}
        with:
          script: |
            const marker = '<!-- nimbus-review-comment -->';
            const checkConclusion = process.env.CHECK_CONCLUSION || 'neutral';
            const findingsCount = process.env.FINDINGS_COUNT || '';
            const staleRun = process.env.STALE_RUN === 'true';

            const pr = context.payload.pull_request;
            const headSha = pr.head.sha;
            const runUrl = `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;

            const checksUrl = `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/pull/${pr.number}/checks`;
            const findingsLabel = findingsCount === '' ? 'unknown' : findingsCount;
            const body = [
              marker,
              '## Nimbus Findings',
              '',
              `- Latest analyzed commit: \`${headSha}\``,
              `- Current result: \`${checkConclusion}\``,
              `- Findings count: \`${findingsLabel}\``,
              `- Detailed findings: ${checksUrl}`,
              `- Workflow run: ${runUrl}`,
              '',
              staleRun
                ? '> This run became stale before publication. A newer run should provide the latest findings.'
                : '> Nimbus posts detailed findings to the Checks tab for consistency; this comment is a stable pointer.',
            ].join('\n');

            const { owner, repo } = context.repo;
            const issue_number = pr.number;

            const comments = await github.paginate(github.rest.issues.listComments, {
              owner,
              repo,
              issue_number,
              per_page: 100,
            });

            const existing = comments
              .filter(c =>
                c.user?.login === 'github-actions[bot]' &&
                typeof c.body === 'string' &&
                c.body.includes(marker)
              )
              .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))[0];

            if (existing) {
              await github.rest.issues.updateComment({
                owner,
                repo,
                comment_id: existing.id,
                body,
              });
              core.info(`Updated existing Nimbus anchor comment: ${existing.id}`);
            } else {
              const created = await github.rest.issues.createComment({
                owner,
                repo,
                issue_number,
                body,
              });
              core.info(`Created Nimbus anchor comment: ${created.data.id}`);
            }

      - name: Finalize as informational check
        if: always()
        run: |
          echo "Nimbus PR review completed (informational mode)."
          exit 0

